const d = $input.first().json.body || $input.first().json;
const TS_SECRET=$env.TURNSTILE_SECRET;
const _tsTok=(d["cf-turnstile-response"]||d.cf_turnstile_response||"");
let cf_ok=false;
try{const _vr=await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"secret="+encodeURIComponent(TS_SECRET)+"&response="+encodeURIComponent(_tsTok)});const _vj=await _vr.json();cf_ok=_vj.success===true;}catch(e){cf_ok=false;}
if(!cf_ok && (/monpermiscpf\.com/i.test(d.url||"") || (d.source||"")==="formulaire-employeur")) cf_ok=true; // bypass Turnstile source de confiance (SMS->form)

const prenom=(d.prenom||"").trim(), nom=(d.nom||"").trim(), email=(d.email||"").trim(), tel=(d.telephone||"").trim();
const formation=d.formation||"", detail=d.formation_detail||formation, situation=d.situation||"", cp=d.code_postal||"";
const route=d.route||"", cpfActif=d.cpf_actif||"", souhaiteCpf=d.souhaite_cpf||"", ftAgence=d.ft_agence||"", ftId=d.ft_identifiant||"";
const prix=Math.round(Number(d.prix_cpf)||0);
const cpfElig=(d.cpf_eligible!==false && d.cpf_eligible!=="false");
const fmt=n=>Number(n).toLocaleString("fr-FR");
const familles={"caces":"CACES","poids-lourd":"permis poids-lourd / transport","ssiap":"SSIAP (sécurité incendie)","securite":"sécurité / habilitation","aipr":"AIPR"};
const famille=familles[formation]||"formation";
const bounds={"caces":[400,2000],"poids-lourd":[1000,3500],"ssiap":[1000,3500],"securite":[80,600],"aipr":[150,450]};
const b=bounds[formation]||[30,4000];
const prixValide = prix>0 && prix>=b[0] && prix<=b[1];
const controle = prixValide ? "OK" : ("A VERIFIER (prix="+prix+" hors bornes ["+b[0]+"-"+b[1]+"] ou absent)");
let resteTxt, financeTxt, cpfTxt="potentiellement jusqu’à 100%";
if(!cpfElig){resteTxt="le montant indiqué (hors CPF)";if(situation==="demandeur"){financeTxt="Cette formation n’est pas finançable par le CPF. En tant que demandeur d’emploi, elle peut être prise en charge par France Travail (dispositif KAIROS) — nous vous accompagnons dans la démarche.";}else if(situation==="salarie"||situation==="fonctionnaire"||situation==="employeur"){financeTxt="Cette formation n’est pas éligible au CPF ; elle est financée par votre employeur ou un OPCO (plan de développement des compétences).";}else if(situation==="perso"){financeTxt="Cette formation n’est pas éligible au CPF ; vous la financez à titre personnel — paiement en plusieurs fois possible.";}else{financeTxt="Cette formation n’est pas éligible au CPF ; elle est financée par votre employeur, un OPCO, France Travail ou en financement personnel.";}}
else if(situation==="demandeur"){cpfTxt="potentiellement jusqu’à 100% (complément France Travail possible)";resteTxt="aucun (sous réserve de vos droits)";financeTxt="Demandeur d’emploi : si vos droits CPF le permettent, la formation peut être prise en charge jusqu’à 100% (complément France Travail possible), sans participation forfaitaire.";}
else if(situation==="salarie"||situation==="fonctionnaire"){cpfTxt="potentiellement jusqu’à 100% + co-financement éventuel (employeur / OPCO)";resteTxt="la participation forfaitaire";financeTxt="Si votre CPF prend en charge la formation, un co-financement employeur ou OPCO peut venir en complément. Il vous reste uniquement la participation forfaitaire.";}
else if(situation==="independant"){resteTxt="la participation forfaitaire";financeTxt="Si votre CPF prend en charge la formation en totalité, il vous reste la participation forfaitaire. Paiement en plusieurs fois possible.";}
else{resteTxt="la participation forfaitaire";financeTxt="Votre CPF peut financer tout ou partie de la formation ; un paiement en plusieurs fois est aussi possible.";}
const cpfLine = cpfElig ? '<tr><td>Prise en charge CPF</td><td style="text-align:right">'+cpfTxt+'</td></tr>' : '';
const sitLabel={"demandeur":"Demandeur d’emploi","salarie":"Salarié","fonctionnaire":"Fonctionnaire","independant":"Indépendant","employeur":"Employeur / OPCO","perso":"Financement personnel"}[situation]||situation;
const subject_benef = prixValide ? ("Votre devis "+famille+" — MonPermisCPF") : ("Accusé de réception de votre demande de devis — "+famille);
let html_benef;
if(prixValide){
  html_benef='<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#2e3d49"><h2 style="color:#1A6BB5">Votre devis</h2><p>Bonjour '+prenom+',</p><p>Voici votre devis pour <strong>'+detail+'</strong> :</p><table cellpadding="8" style="width:100%;border-collapse:collapse;background:#f8f9fa;border-radius:8px"><tr><td>Formation</td><td style="text-align:right"><strong>'+detail+'</strong></td></tr><tr><td>Tarif de la formation</td><td style="text-align:right">'+fmt(prix)+' EUR</td></tr>'+cpfLine+'<tr><td><strong>Reste à votre charge</strong></td><td style="text-align:right"><strong>'+resteTxt+'</strong></td></tr></table><p>'+financeTxt+'</p><p>Pensez à vérifier que vous disposez d’un compte CPF actif sur moncompteformation.gouv.fr.</p><p style="font-size:12px;color:#6c757d">Devis indicatif établi selon les informations communiquées, <strong>sous réserve de vérification</strong> de votre éligibilité au CPF et de votre situation. Tarif susceptible d’ajustement après étude du dossier. Valable 1 mois.</p><p>Une question ? Lucie vous répond — <a href="tel:+33974991515">09 74 99 15 15</a>.</p><p style="color:#6c757d;font-size:13px">MonPermisCPF — certifié Qualiopi — SASU Monpermiscpf.com</p></div>';
}else{
  html_benef='<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#2e3d49"><h2 style="color:#1A6BB5">Accusé de réception de votre demande de devis</h2><p>Bonjour '+prenom+',</p><p>Nous avons bien reçu votre demande de devis concernant <strong>'+detail+'</strong>.</p><p>Un conseiller vérifie votre dossier et vous adresse votre <strong>devis détaillé sous 24h</strong>.</p><p>'+financeTxt+'</p><p>Une question ? Lucie vous répond — <a href="tel:+33974991515">09 74 99 15 15</a>.</p><p style="color:#6c757d;font-size:13px">MonPermisCPF — certifié Qualiopi</p></div>';
}
const subject_interne=(prixValide?"":"[A VERIFIER] ")+"Devis "+famille+" — "+detail+" ("+(cp||"?")+")";
const html_interne='<h3>Demande de devis (simulateur)</h3>'+(prixValide?'':'<p style="color:#a01a3c"><strong>CONTROLE : '+controle+' — devis chiffré NON envoyé, accusé seulement.</strong></p>')+'<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><td>Prénom</td><td>'+prenom+'</td></tr><tr><td>Nom</td><td>'+nom+'</td></tr><tr><td>Email</td><td>'+email+'</td></tr><tr><td>Téléphone</td><td>'+(tel||"-")+'</td></tr><tr><td>Formation</td><td>'+detail+'</td></tr><tr><td>Situation</td><td>'+sitLabel+'</td></tr><tr><td>Code postal</td><td>'+cp+'</td></tr><tr><td>Tarif</td><td>'+(prix>0?fmt(prix)+" EUR":"-")+'</td></tr><tr><td>Controle prix</td><td>'+controle+'</td></tr></table>'+(situation==="demandeur"?('<table border="1" cellpadding="6" style="border-collapse:collapse;margin-top:8px"><tr><td>Routage</td><td><strong>'+(route==="edof"?"EDOF (CPF)":"France Travail / KAIROS")+'</strong></td></tr><tr><td>Compte CPF actif</td><td>'+cpfActif+'</td></tr><tr><td>Souhaite financer via CPF</td><td>'+souhaiteCpf+'</td></tr>'+(ftAgence?'<tr><td>Agence France Travail</td><td>'+ftAgence+'</td></tr>':'')+(ftId?'<tr><td>Identifiant France Travail</td><td>'+ftId+'</td></tr>':'')+'</table>'):'');
const now=new Date(),j1=new Date(now),j3=new Date(now);j1.setDate(j1.getDate()+1);j3.setDate(j3.getDate()+3);
const external_id="DEVISWEB-"+now.getTime();
const pad=x=>(""+x).padStart(2,"0");
const dateStr=pad(now.getDate())+"/"+pad(now.getMonth()+1)+"/"+now.getFullYear();
const vd=new Date(now);vd.setMonth(vd.getMonth()+1);const validStr=pad(vd.getDate())+"/"+pad(vd.getMonth()+1)+"/"+vd.getFullYear();
const pdfCpfRow = cpfElig ? '<tr><td style="padding:8px;border-bottom:1px solid #eee">Prise en charge CPF</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right">'+cpfTxt+'</td></tr>' : '';
const pdfCpfNote = cpfElig ? '<p style="font-size:13px;color:#555">Pensez à vérifier que vous disposez d’un compte CPF actif sur moncompteformation.gouv.fr.</p>' : '';
const html_pdf='<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:Arial,Helvetica,sans-serif;color:#2e3d49;margin:0;padding:32px">'
+'<div style="display:flex;justify-content:space-between;border-bottom:3px solid #1A6BB5;padding-bottom:12px"><div><div style="font-size:24px;font-weight:bold;color:#1A6BB5">MonPermisCPF</div><div style="font-size:12px;color:#6c757d">Organisme de formation certifié Qualiopi</div></div><div style="text-align:right"><div style="font-size:22px;font-weight:bold;color:#1A6BB5">DEVIS</div><div style="font-size:12px;color:#6c757d">N° '+external_id+'<br>Le '+dateStr+'<br>Valable jusqu’au '+validStr+'</div></div></div>'
+'<p style="margin-top:18px"><strong>Destinataire :</strong> '+prenom+' '+nom+(email?' — '+email:'')+(tel?' — '+tel:'')+'</p>'
+'<table style="width:100%;border-collapse:collapse;margin:18px 0;background:#f8f9fa;border-radius:8px"><tr><td style="padding:8px;border-bottom:1px solid #eee">Formation</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right"><strong>'+detail+'</strong></td></tr><tr><td style="padding:8px;border-bottom:1px solid #eee">Tarif de la formation</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right">'+fmt(prix)+' EUR</td></tr>'+pdfCpfRow+'<tr><td style="padding:8px"><strong>Reste à votre charge</strong></td><td style="padding:8px;text-align:right"><strong>'+resteTxt+'</strong></td></tr></table>'
+'<p>'+financeTxt+'</p>'+pdfCpfNote
+'<p style="font-size:11px;color:#6c757d;border-top:1px solid #eee;padding-top:10px;margin-top:18px">Devis indicatif établi selon les informations communiquées, sous réserve de vérification de votre éligibilité au CPF et de votre situation. Tarif susceptible d’ajustement après étude du dossier. Valable 1 mois à compter de la date d’émission.</p>'
+'<p style="font-size:12px;color:#6c757d">Une question ? Lucie vous répond — 09 74 99 15 15</p>'
+'<div style="font-size:11px;color:#6c757d;border-top:3px solid #1A6BB5;padding-top:8px;margin-top:12px">MonPermisCPF — SASU Monpermiscpf.com — RCS Meaux 884 335 290 — NDA 11770705377 — certifié Qualiopi</div></body></html>';
return [{json:{cf_ok,email,prenom,nom,tel,formation,detail,situation,cp,prix,prixValide,controle,subject_benef,html_benef,subject_interne,html_interne,html_pdf,external_id,route,ft_identifiant:ftId,ft_agence:ftAgence,relance_j1_at:j1.toISOString(),relance_j3_at:j3.toISOString()}}];

const p = $('Preparer devis').item.json;
const b64 = ($json.pdf_base64)||"";
return [{ json: { email:p.email, subject_benef:p.subject_benef, html_benef:p.html_benef }, binary: b64 ? { devis_pdf: { data:b64, mimeType:"application/pdf", fileName:"devis-monpermiscpf.pdf", fileExtension:"pdf" } } : {} }];
